1	package wallet
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// approvalPolicy 构造一条开启大额审批的策略：门槛 10，等待 1 分钟，
12	// 其余与 validPolicy 一致（单次 30、累计 50、窗口 1 小时）。
13	func approvalPolicy(c *clock) PolicySpec {
14		p := validPolicy(c)
15		p.ID = "p-approval"
16		p.ApprovalThreshold = 10
17		p.ApprovalWait = time.Minute
18		return p
19	}
20	
21	// setupApproval 构造带审批策略的钱包：出资账户 payer（100），使用账户
22	// u1/u2，会话 s1/s2，以及出资账户绑定审批设备的会话 sa。
23	func setupApproval(t *testing.T) (*Wallet, *clock) {
24		t.Helper()
25		w, c := newTestWallet()
26		mustAccount(t, w, "payer", 100)
27		mustAccount(t, w, "u1", 0)
28		mustAccount(t, w, "u2", 0)
29		if _, err := w.CreateSession("s1", "u1", "dev1", c.t.Add(time.Minute)); err != nil {
30			t.Fatal(err)
31		}
32		if _, err := w.CreateSession("s2", "u2", "dev2", c.t.Add(time.Minute)); err != nil {
33			t.Fatal(err)
34		}
35		if _, err := w.CreateSession("sa", "payer", "dev-approve", c.t.Add(time.Hour)); err != nil {
36			t.Fatal(err)
37		}
38		if err := w.SavePolicy(approvalPolicy(c)); err != nil {
39			t.Fatal(err)
40		}
41		return w, c
42	}
43	
44	func approvalApply() RequestInput {
45		return RequestInput{
46			PolicyID:     "p-approval",
47			RequestID:    "r1",
48			AccountID:    "u1",
49			SessionID:    "s1",
50			DeviceID:     "dev1",
51			Operation:    "charge",
52			Payee:        "shop",
53			EstimatedFee: 20,
54		}
55	}
56	
57	func TestSaveApprovalPolicyValidation(t *testing.T) {
58		w, c := newTestWallet()
59		mustAccount(t, w, "payer", 100)
60		mustAccount(t, w, "u1", 0)
61		mustAccount(t, w, "u2", 0)
62	
63		good := approvalPolicy(c)
64		if err := w.SavePolicy(good); err != nil {
65			t.Fatal(err)
66		}
67		// 视图能读回审批配置。
68		pv, err := w.Policy("p-approval")
69		if err != nil {
70			t.Fatal(err)
71		}
72		if pv.ApprovalThreshold != 10 || pv.ApprovalWait != time.Minute {
73			t.Fatalf("approval config = threshold %d wait %v", pv.ApprovalThreshold, pv.ApprovalWait)
74		}
75	
76		cases := []struct {
77			name   string
78			mutate func(*PolicySpec)
79		}{
80			{"negative threshold", func(p *PolicySpec) { p.ApprovalThreshold = -1 }},
81			{"threshold exceeds per-request", func(p *PolicySpec) { p.ApprovalThreshold = 31 }},
82			{"zero wait when enabled", func(p *PolicySpec) { p.ApprovalWait = 0 }},
83			{"negative wait when enabled", func(p *PolicySpec) { p.ApprovalWait = -time.Second }},
84		}
85		for _, tc := range cases {
86			t.Run(tc.name, func(t *testing.T) {
87				bad := good
88				bad.ID = "p-bad-" + tc.name
89				tc.mutate(&bad)
90				if err := w.SavePolicy(bad); !errors.Is(err, ErrPolicyInvalid) {
91					t.Fatalf("err = %v, want ErrPolicyInvalid", err)
92				}
93			})
94		}
95	
96		// 门槛为零（关闭审批）时等待时长不做要求。
97		off := good
98		off.ID = "p-off"
99		off.ApprovalThreshold = 0
100		off.ApprovalWait = 0
101		if err := w.SavePolicy(off); err != nil {
102			t.Fatalf("disabled approval with zero wait should be accepted: %v", err)
103		}
104		// 门槛恰好等于单次上限允许保存（费用不可能严格超过它）。
105		eq := good
106		eq.ID = "p-eq"
107		eq.ApprovalThreshold = 30
108		if err := w.SavePolicy(eq); err != nil {
109			t.Fatalf("threshold equal to per-request cap should be accepted: %v", err)
110		}
111	}
112	
113	func TestApplyGoesPendingWithoutFreezing(t *testing.T) {
114		w, c := setupApproval(t)
115	
116		in := approvalApply()
117		req, err := w.Apply(in)
118		if err != nil {
119			t.Fatal(err)
120		}
121		if req.State != RequestPendingApproval {
122			t.Fatalf("state = %v, want pending approval", req.State)
123		}
124		// 等待期限 = min(提交+1分钟, 策略结束, 会话到期) = 提交+1分钟。
125		wantDeadline := c.t.Add(time.Minute)
126		if !req.WaitDeadline.Equal(wantDeadline) {
127			t.Fatalf("wait deadline = %v, want %v", req.WaitDeadline, wantDeadline)
128		}
129		if req.DecidedAt != (time.Time{}) || req.ApproverAccountID != "" || req.RejectReason != "" {
130			t.Fatalf("pending request should have no decision yet: %+v", req)
131		}
132	
133		// 待审批不冻结余额、不占用共享累计额度。
134		bal, _ := w.Balance("payer")
135		if bal != (Balances{Available: 100, Reserved: 0}) {
136			t.Fatalf("balance = %+v, want untouched {100 0}", bal)
137		}
138		pv, _ := w.Policy("p-approval")
139		if pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
140			t.Fatalf("policy totals = reserved %d spent %d, want 0/0", pv.ReservedTotal, pv.SpentTotal)
141		}
142		if len(w.AccountLedger("payer")) != 0 {
143			t.Fatal("pending approval must not create money-moving ledger entries")
144		}
145	
146		// 账本含待审批状态留痕，关联使用账户与请求号。
147		var found bool
148		for _, e := range w.Ledger() {
149			if e.Kind == LedgerPendingApproval {
150				found = true
151				if e.AccountID != "u1" || e.RequestID != "r1" || e.Amount != 0 {
152					t.Fatalf("pending ledger entry = %+v", e)
153				}
154			}
155		}
156		if !found {
157			t.Fatal("missing LedgerPendingApproval entry")
158		}
159	
160		// 等于门槛的费用直接预留，不进入待审批。
161		eq := approvalApply()
162		eq.RequestID = "r-eq"
163		eq.EstimatedFee = 10
164		eqReq, err := w.Apply(eq)
165		if err != nil {
166			t.Fatal(err)
167		}
168		if eqReq.State != RequestReserved {
169			t.Fatalf("fee equal to threshold state = %v, want reserved", eqReq.State)
170		}
171		// 低于门槛直接预留。
172		low := approvalApply()
173		low.RequestID = "r-low"
174		low.EstimatedFee = 9
175		lowReq, err := w.Apply(low)
176		if err != nil {
177			t.Fatal(err)
178		}
179		if lowReq.State != RequestReserved {
180			t.Fatalf("fee below threshold state = %v, want reserved", lowReq.State)
181		}
182	}
