	}
	if !req2.WaitDeadline.Equal(sessExp) {
		t.Fatalf("deadline = %v, want session expiry %v", req2.WaitDeadline, sessExp)
	}
}

func TestSessionRevocationRejectsPendingOnly(t *testing.T) {
